class Animal:
    def __init__(self, name):
        self.name = name

    def __str__(self):
        return f"Animal[{self.name}]"

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name)
        self.breed = breed

    def __str__(self):
        base = super().__str__()
        return base + f", Breed[{self.breed}]"

print(Dog("Rex", "Corgi"))

